ns16:scriptTask.ns16:script:
// stepName? make -> editable : readonly

if(tw.local.stepName == "maker"){
	tw.local.sumVis = 'None';
	tw.local.tableVis = "Editable";
}

else {
	tw.local.sumVis = 'Editable';
	tw.local.tableVis = "ReadOnly"
}

